create function pg_temp.tpl_restore(j jsonb) returns jsonb language plpgsql as $f$
begin
 if jsonb_typeof(j)='string' and j#>>'{}' ~ '^__T[0-9]+__$' then return pg_temp.tpl_t(substring(j#>>'{}' from 4 for length(j#>>'{}')-5)::integer);end if;
 if jsonb_typeof(j)='object' then return coalesce((select jsonb_object_agg(key,pg_temp.tpl_restore(value)) from jsonb_each(j)),'{}'::jsonb);end if;
 if jsonb_typeof(j)='array' then return coalesce((select jsonb_agg(pg_temp.tpl_restore(value) order by ord) from jsonb_array_elements(j) with ordinality a(value,ord)),'[]'::jsonb);end if;
 return j;
end $f$;
