begin
generous:=jsonb_set(settings,'{pricing,templates,0,pricing,maxDiscount}','20');
cycle:=jsonb_set(jsonb_set(settings,'{pricing,templates,0,computed,0,expression}','{"op":"name","args":["cards_required"]}'),'{pricing,templates,0,computed,1,expression}','{"op":"name","args":["paper_required"]}');
bad_tree:=jsonb_set(settings,'{pricing,templates,0,expenses,0,expression}','{"op":"EVAL","args":[]}');
insert into auth.users(id,email,raw_user_meta_data,created_at) values('a0000000-0000-4000-8000-000000000001','pricing-template-test@example.invalid','{}',now());
perform set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
insert into public.shops(name) values('Pricing template integration test') returning id into shop;
insert into public.shop_members(shop_id,user_id,role,rank,access_level,name,username) values(shop,'a0000000-0000-4000-8000-000000000001','developer',4,4,'Template tester','template-test');
-- Decimal parity with the app: 15 random formulas.
for p in select value from jsonb_array_elements(parity) loop
 if private.tpl_text(private.tpl_eval(p->0,'{}'::jsonb)) is distinct from p->>1 then raise exception 'Decimal result differs: % gives % not %',p->0,private.tpl_text(private.tpl_eval(p->0,'{}'::jsonb)),p->>1;end if;
end loop;
perform public.apply_customer_event(shop,pg_temp.tpl_restore($json${"id":"af3efcb1-1ac6-4806-a89a-c6e7e7685671","kind":"customer.created","data":{"id":"a0000000-0000-4000-8000-000000000002","name":"Book customer","phone":"080template","address":"","creditLimit":0,"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
perform public.apply_material_event(shop,pg_temp.tpl_restore($json${"id":"c0000000-0000-4000-8000-000000000001","kind":"material.created","data":{"id":"a0000000-0000-4000-8000-000000000003","name":"Paper 70gsm","available":2000,"measurementUnit":"sheet","requireSize":false,"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
perform public.apply_material_event(shop,pg_temp.tpl_restore($json${"id":"c0000000-0000-4000-8000-000000000002","kind":"material.created","data":{"id":"a0000000-0000-4000-8000-000000000004","name":"Paper 80gsm","available":2000,"measurementUnit":"sheet","requireSize":false,"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
