perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000002","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000006","description":"Paper 80gsm","materialId":"a0000000-0000-4000-8000-000000000004","price":0,"private":true,"costing":{"key":"paper_80","amount":650000,"per":500,"unit":"ream"},"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000003","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000007","description":"Art card","materialId":"a0000000-0000-4000-8000-000000000010","price":20000,"shelfItem":true,"private":false,"costing":{"key":"art_card","amount":20000,"per":1},"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000004","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000008","description":"Binding labour","materialId":null,"price":0,"private":true,"costing":{"key":"binding","amount":10000,"per":1},"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000005","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000041","description":"Cost shirt_cost","materialId":null,"price":0,"private":true,"costing":{"key":"shirt_cost","amount":200000,"per":1},"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000006","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000042","description":"Cost dtf_rate","materialId":null,"price":0,"private":true,"costing":{"key":"dtf_rate","amount":160000,"per":1},"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));
