-- Formula names are unique, valid, and a private item needs a cost.
begin perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000070","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000070","description":"Dup","materialId":null,"price":0,"private":false,"costing":{"key":"binding","amount":1,"per":1},"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));raise exception 'Duplicate formula name accepted';exception when sqlstate 'PT409' then null;end;
begin perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000071","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000071","description":"Bad","materialId":null,"price":0,"private":false,"costing":{"key":"Bad Key","amount":1,"per":1},"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));raise exception 'Invalid formula name accepted';exception when raise_exception then if sqlerrm not like 'Enter a valid template cost%' then raise;end if;end;
begin perform public.apply_service_event(shop,pg_temp.tpl_restore($json${"id":"b0000000-0000-4000-8000-000000000072","kind":"service.created","data":{"id":"a0000000-0000-4000-8000-000000000072","description":"Uncosted","materialId":null,"price":0,"private":true,"costing":null,"modifiedBy":"a0000000-0000-4000-8000-000000000001","modifiedByLabel":"Template tester","modifiedAt":"2026-10-13T08:00:00Z"}}$json$::jsonb));raise exception 'Private item without cost accepted';exception when raise_exception then if sqlerrm not like 'A templates-only item%' then raise;end if;end;
if (select count(*) from public.services where shop_id=shop and private)<>7 or (select costing->>'key' from public.services where shop_id=shop and id='a0000000-0000-4000-8000-000000000005')<>'paper_70' then raise exception 'Service costs not stored';end if;
if (public.get_ledger(shop)->'services'->0) ? 'costing' is not true then raise exception 'Ledger lacks service costs';end if;
-- Saving templates: loops and unknown formula parts are refused.
begin perform public.save_business_settings(shop,coalesce((select version from public.business_settings where shop_id=shop),0),cycle);raise exception 'Circular template accepted';exception when raise_exception then if sqlerrm not like 'Circular calculation%' then raise;end if;end;
begin perform public.save_business_settings(shop,coalesce((select version from public.business_settings where shop_id=shop),0),bad_tree);raise exception 'Bad formula accepted';exception when raise_exception then if sqlerrm not like 'Unsupported template formula%' then raise;end if;end;
perform public.save_business_settings(shop,coalesce((select version from public.business_settings where shop_id=shop),0),settings);
execute 'set local role authenticated';
-- A quotation (book + margin-priced shirts) is checked but posts nothing.
perform public.apply_quotation_event(shop,quotation);
if (select count(*) from public.jobs where shop_id=shop)<>0 or (select available from public.materials where shop_id=shop and id='a0000000-0000-4000-8000-000000000003')<>2000 then raise exception 'Quotation posted stock or a job';end if;
changed:=jsonb_set(quotation,'{id}','"a0000000-0000-4000-8000-000000000097"');changed:=jsonb_set(changed,'{data,lines,1,templateSnapshot,price,amount}','1');changed:=jsonb_set(changed,'{data,lines,1,grossAmount}','1');
begin perform public.apply_quotation_event(shop,changed);raise exception 'Tampered quotation accepted';exception when sqlstate 'PT409' then null;end;
-- Tampered prices, costs or stock are refused.
changed:=jsonb_set(e,'{data,jobs,0,templateSnapshot,expenses,0,amount}','"6400"');
begin perform public.apply_checkout_event(shop,changed);raise exception 'Tampered expense accepted';exception when sqlstate 'PT409' then null;end;
changed:=jsonb_set(e,'{data,jobs,0,templateSnapshot,stock,0,quantity}','1');
begin perform public.apply_checkout_event(shop,changed);raise exception 'Tampered stock accepted';exception when sqlstate 'PT409' then null;end;
execute 'reset role';update public.services set costing=jsonb_set(costing,'{amount}','510000') where shop_id=shop and id='a0000000-0000-4000-8000-000000000005';execute 'set local role authenticated';
begin perform public.apply_checkout_event(shop,e);raise exception 'Stale cost accepted';exception when sqlstate 'PT409' then null;end;
execute 'reset role';update public.services set costing=jsonb_set(costing,'{amount}','500000') where shop_id=shop and id='a0000000-0000-4000-8000-000000000005';execute 'set local role authenticated';
perform public.apply_checkout_event(shop,e);
if (select count(*) from public.jobs where shop_id=shop)<>1 or (select amount from public.jobs where shop_id=shop and id='a0000000-0000-4000-8000-000000000020')<>2880000 then raise exception 'Book job incorrect';end if;
if (select available from public.materials where shop_id=shop and id='a0000000-0000-4000-8000-000000000003')<>1350 or (select available from public.materials where shop_id=shop and id='a0000000-0000-4000-8000-000000000010')<>47 or (select available from public.materials where shop_id=shop and id='a0000000-0000-4000-8000-000000000004')<>2000 then raise exception 'Stock deducted incorrectly';end if;
if (select count(*) from public.material_stock_changes where shop_id=shop and action='material.job_used')<>2 then raise exception 'Stock history incomplete';end if;
perform public.apply_checkout_event(shop,e);
if (select available from public.materials where shop_id=shop and id='a0000000-0000-4000-8000-000000000003')<>1350 then raise exception 'Retry deducted again';end if;
-- Discounts above the template maximum (5%) or below its minimum price are refused.
changed:=jsonb_set(second,'{data,jobs,0,discount}','{"kind":"percent","value":6}');
changed:=jsonb_set(changed,'{data,jobs,0,lineDiscount}','172800');changed:=jsonb_set(changed,'{data,jobs,0,discountAmount}','172800');changed:=jsonb_set(changed,'{data,jobs,0,grossAmount}','2880000');changed:=jsonb_set(changed,'{data,jobs,0,amount}','2707200');
changed:=jsonb_set(changed,'{data,total}','2707200');changed:=jsonb_set(changed,'{data,outstandingBefore}',to_jsonb((second->'data'->>'outstandingBefore')::numeric-172800));changed:=jsonb_set(changed,'{data,outstandingAfter}',to_jsonb((second->'data'->>'outstandingAfter')::numeric-172800));
begin perform public.apply_checkout_event(shop,changed);raise exception 'Over-maximum discount accepted';exception when sqlstate 'PT409' then if sqlerrm not like 'This discount is outside%' then raise;end if;end;
-- A templates-only item cannot be sold.
begin perform public.apply_checkout_event(shop,private_sale);raise exception 'Private item sold';exception when sqlstate 'PT409' then if sqlerrm not like '%templates only%' then raise;end if;end;
perform public.apply_checkout_event(shop,second);
if (select available from public.materials where shop_id=shop and id='a0000000-0000-4000-8000-000000000003')<>700 then raise exception 'Second book stock incorrect';end if;
-- Disabled templates stop new sales.
execute 'reset role';
changed:=jsonb_set(settings,'{pricing,enabled}','false');
perform public.save_business_settings(shop,(select version from public.business_settings where shop_id=shop),changed);
execute 'set local role authenticated';
begin perform public.apply_checkout_event(shop,jsonb_set(jsonb_set(e,'{id}','"a0000000-0000-4000-8000-000000000098"'),'{data,id}','"a0000000-0000-4000-8000-000000000098"'));raise exception 'Disabled template accepted';exception when sqlstate 'PT409' then null;end;
execute 'reset role';
raise exception 'PRICING_TEMPLATES_TEST_PASSED';
end $test$;
rollback;
